import { Combobox as BaseCombobox } from '@base-ui/react/combobox';
import { Check, ChevronDown, X } from 'lucide-react';
import { useId, useRef, useState, type ReactNode, type Ref } from 'react';
import { usePortalDir, useI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { comboboxVariants } from '../combobox/combobox.variants';
import { multiSelectVariants, type MultiSelectVariantProps } from './multi-select.variants';

const cb = comboboxVariants();

export interface MultiSelectOption {
  value: string;
  label: string;
  /** Secondary line under the label. */
  description?: string;
  disabled?: boolean;
}

export interface MultiSelectProps extends MultiSelectVariantProps {
  options: MultiSelectOption[];
  /** Selected option values (controlled). */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (values: string[]) => void;
  /** Visible label bound to the input. Inside a Field, use FieldLabel instead. */
  label?: ReactNode;
  placeholder?: string;
  /** Chips shown before collapsing the rest into "+N". */
  maxVisibleChips?: number;
  /** Adds a "Select all" row (while the search is empty). */
  showSelectAll?: boolean;
  selectAllLabel?: string;
  /** Label of the same row once every option is selected. */
  deselectAllLabel?: string;
  clearLabel?: string;
  triggerLabel?: string;
  emptyText?: ReactNode;
  removeLabel?: (label: string) => string;
  /** Custom row content. */
  renderOption?: (option: MultiSelectOption) => ReactNode;
  name?: string;
  id?: string;
  disabled?: boolean;
  invalid?: boolean;
  className?: string;
  ref?: Ref<HTMLInputElement>;
  'aria-label'?: string;
  'aria-describedby'?: string;
}

const SELECT_ALL: MultiSelectOption = { value: '\u0000select-all', label: '' };
const matches = (o: MultiSelectOption, q: string) =>
  o === SELECT_ALL ? q.trim() === '' : `${o.label} ${o.description ?? ''}`.toLowerCase().includes(q.trim().toLowerCase());

/**
 * Searchable multi-select on Base UI Combobox (multiple): selected options as removable chips
 * (extra ones collapse into "+N"), an optional "Select all" row and a clear button.
 */
export function MultiSelect({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  placeholder: placeholderProp,
  maxVisibleChips = 3,
  showSelectAll = true,
  selectAllLabel: selectAllLabelProp,
  deselectAllLabel: deselectAllLabelProp,
  clearLabel: clearLabelProp,
  triggerLabel: triggerLabelProp,
  emptyText: emptyTextProp,
  removeLabel = (l) => `Remove ${l}`,
  renderOption,
  name,
  id,
  disabled,
  invalid,
  size = 'md',
  className,
  ref,
  'aria-label': ariaLabel,
  'aria-describedby': ariaDescribedBy,
}: MultiSelectProps) {
  const { t } = useI18n();
  const placeholder = placeholderProp ?? t('common.searchPlaceholder');
  const selectAllLabel = selectAllLabelProp ?? t('common.selectAll');
  const deselectAllLabel = deselectAllLabelProp ?? t('common.deselectAll');
  const clearLabel = clearLabelProp ?? t('common.clearAll');
  const triggerLabel = triggerLabelProp ?? t('common.showOptions');
  const emptyText = emptyTextProp ?? t('common.noMatches');
  const dir = usePortalDir();
  const autoId = useId();
  const inputId = id ?? (label ? autoId : undefined);
  const [inner, setInner] = useState<string[]>(defaultValue ?? []);
  const values = value ?? inner;
  // While the popup is open Base UI aria-hides outside nodes, <label> included; aria-labelledby
  // still resolves through hidden elements, so a Field label's id is mirrored onto the input.
  const [fieldLabelId, setFieldLabelId] = useState<string | undefined>();
  const inputRef = useRef<HTMLInputElement | null>(null);
  const setRefs = (node: HTMLInputElement | null) => {
    inputRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  };
  const selected = values.map((v) => options.find((o) => o.value === v)).filter((o): o is MultiSelectOption => !!o);
  const enabled = options.filter((o) => !o.disabled);
  const allSelected = enabled.length > 0 && enabled.every((o) => values.includes(o.value));
  const items = showSelectAll ? [SELECT_ALL, ...options] : options;
  const s = multiSelectVariants({ size });
  const v = comboboxVariants({ size });

  const commit = (next: string[]) => {
    setInner(next);
    onValueChange?.(next);
  };

  const handleChange = (next: MultiSelectOption[]) => {
    if (next.includes(SELECT_ALL)) {
      const enabledValues = enabled.map((o) => o.value);
      commit(allSelected ? values.filter((x) => !enabledValues.includes(x)) : [...values, ...enabledValues.filter((x) => !values.includes(x))]);
      return;
    }
    commit(next.map((o) => o.value));
  };

  const visible = selected.slice(0, maxVisibleChips);
  const hidden = selected.length - visible.length;

  return (
    <BaseCombobox.Root
      items={items}
      multiple
      value={selected}
      onValueChange={handleChange}
      filter={matches}
      isItemEqualToValue={(a: MultiSelectOption, b: MultiSelectOption) => a.value === b.value}
      itemToStringLabel={(o: MultiSelectOption) => o.label}
      itemToStringValue={(o: MultiSelectOption) => o.value}
      name={name}
      disabled={disabled}
      onOpenChange={(open) => {
        if (open && !label) setFieldLabelId(inputRef.current?.labels?.[0]?.id || undefined);
      }}
    >
      {label && (
        <label id={`${inputId}-label`} htmlFor={inputId} className={cb.label()}>
          {label}
        </label>
      )}
      <BaseCombobox.InputGroup className={cn(cb.chipsGroup(), s.group(), className)} data-invalid={invalid || undefined}>
        <BaseCombobox.Chips className={cb.chips()}>
          {visible.map((o) => (
            <BaseCombobox.Chip key={o.value} className={cb.chip()} aria-label={o.label}>
              {o.label}
              <BaseCombobox.ChipRemove aria-label={removeLabel(o.label)} className={cb.chipRemove()}>
                <X size={11} strokeWidth={2.4} aria-hidden />
              </BaseCombobox.ChipRemove>
            </BaseCombobox.Chip>
          ))}
          {hidden > 0 && (
            <span className={s.more()}>
              +{hidden}
              <span className="sr-only"> {t('multiSelect.moreSelected')}</span>
            </span>
          )}
          <BaseCombobox.Input
            ref={setRefs}
            id={inputId}
            aria-labelledby={label ? `${inputId}-label` : ariaLabel ? undefined : fieldLabelId}
            aria-label={ariaLabel}
            aria-describedby={ariaDescribedBy}
            aria-invalid={invalid || undefined}
            placeholder={selected.length ? undefined : placeholder}
            className={cb.chipsInput()}
          />
        </BaseCombobox.Chips>
        {selected.length > 0 && (
          <BaseCombobox.Clear aria-label={clearLabel} className={v.iconButton()}>
            <X size={14} aria-hidden />
          </BaseCombobox.Clear>
        )}
        <BaseCombobox.Trigger aria-label={triggerLabel} className={cn('group', v.iconButton())}>
          <ChevronDown size={15} aria-hidden className={cb.chevron()} />
        </BaseCombobox.Trigger>
      </BaseCombobox.InputGroup>
      <BaseCombobox.Portal>
        <BaseCombobox.Positioner dir={dir} className={cb.positioner()} side="bottom" align="start" sideOffset={6}>
          <BaseCombobox.Popup className={cb.popup()}>
            <BaseCombobox.Empty className={cb.empty()}>{emptyText}</BaseCombobox.Empty>
            <BaseCombobox.List className={cb.list()}>
              {(o: MultiSelectOption) =>
                o === SELECT_ALL ? (
                  <BaseCombobox.Item key={o.value} value={o} className={cn(cb.item(), s.selectAll())}>
                    <span className={cb.itemContent()}>{allSelected ? deselectAllLabel : selectAllLabel}</span>
                    <span className={s.check()}>{allSelected && <Check size={15} strokeWidth={2.4} aria-hidden />}</span>
                  </BaseCombobox.Item>
                ) : (
                  <BaseCombobox.Item key={o.value} value={o} disabled={o.disabled} className={cb.item()}>
                    <span className={cb.itemContent()}>
                      {renderOption ? (
                        renderOption(o)
                      ) : (
                        <span className="min-w-0">
                          <span className="block truncate">{o.label}</span>
                          {o.description && <span className={s.description()}>{o.description}</span>}
                        </span>
                      )}
                    </span>
                    <BaseCombobox.ItemIndicator className={cb.indicator()}>
                      <Check size={15} strokeWidth={2.4} aria-hidden />
                    </BaseCombobox.ItemIndicator>
                  </BaseCombobox.Item>
                )
              }
            </BaseCombobox.List>
          </BaseCombobox.Popup>
        </BaseCombobox.Positioner>
      </BaseCombobox.Portal>
    </BaseCombobox.Root>
  );
}

export { MultiSelect, type MultiSelectProps, type MultiSelectOption } from './MultiSelect';
export { multiSelectVariants, type MultiSelectVariantProps } from './multi-select.variants';
export { doc as multiSelectDoc } from './MultiSelect.doc';

import { tv, type VariantProps } from '../../utils/tv';

/** Extra slots on top of the Combobox house styles (chips field, popup, rows). */
export const multiSelectVariants = tv({
  slots: {
    group: [
      'flex w-full min-w-0 items-center gap-1 pe-1',
      'data-invalid:border-destructive/70 has-[input[aria-invalid=true]]:border-destructive/70',
    ],
    more: 'inline-flex h-6 shrink-0 items-center rounded bg-secondary px-1.5 font-mono text-[11.5px] font-medium text-muted-foreground',
    selectAll: 'mb-1 rounded-b-none border-b border-border font-medium',
    description: 'block truncate text-[11.5px] text-muted-foreground',
    check: 'flex size-4 shrink-0 items-center justify-center text-primary-text',
  },
  variants: {
    size: {
      sm: { group: 'min-h-8 py-0.5 ps-1.5' },
      md: { group: 'min-h-9 py-1 ps-2' },
    },
  },
  defaultVariants: { size: 'md' },
});

export type MultiSelectVariantProps = VariantProps<typeof multiSelectVariants>;

import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({ locale, messages, dir, applyTo = 'wrapper', children }: I18nProviderProps) {
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, ...createFormatters(locale, merged) };
  }, [locale, messages, direction]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages): I18nFormatters {
  function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now = unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatCurrency: (value, currency, options) => new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate: (value, options = { dateStyle: 'medium' }) => new Intl.DateTimeFormat(locale, options).format(toDate(value)),
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) => new Intl.ListFormat(locale, options).format(items),
  };
}

import { en, type Messages } from './en';
import { es } from './es';

/** Built-in catalogs, by language subtag. */
export const catalogs = { en, es } satisfies Record<string, Messages>;
export type CatalogLocale = keyof typeof catalogs;
